 const extra='<section class="shell" style="padding-block:45px"><article style="background:#fff;border:1px solid #dfe8dc;border-radius:17px;padding:32px"><div class="label">'+metal.symbol+' / INVESTMENT EDUCATION</div><h2 style="margin:12px 0 18px">'+metal.name+' ownership & market research</h2><p style="max-width:850px;color:#6a7c6c;line-height:1.95">'+metal.text+'</p><p style="margin-top:17px;color:#6a7c6c;font-size:12px">Reference market sources: <a style="color:#9c753f;text-decoration:underline" href="https://gold-api.com/docs">Gold API</a>. Financial product terms: always verify with the named provider. No investment is made on this page.</p><a href="/?view=converter" class="btn" style="margin-top:19px">Calculate '+metal.name+' reference value ↗</a></article></section>';
 return HTML.replace(/<title>[^<]*<\/title>/,'<title>'+metal.title+'</title>')
 .replace(/<meta name="description" content="[^"]*">/,'<meta name="description" content="'+metal.description+'">'+head)
