let priceCache:any=null,priceExpires=0,dbInit:Promise<any>|null=null;
const rates=new Map<string,{count:number,reset:number}>();
function json(o:any,status=200){return new Response(JSON.stringify(o),{status,headers:{"content-type":"application/json; charset=utf-8","cache-control":"no-store","x-content-type-options":"nosniff","referrer-policy":"no-referrer"}})}
function fail(m:string,s=400){return json({ok:false,error:m},s)}
function clean(x:any,len=150){return String(x==null?"":x).trim().slice(0,len)}
function emailOk(x:string){return x.length<255&&/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(x)}
function limit(r:Request,name:string,max=5,window=3600000){const ip=clean((r.headers.get("x-forwarded-for")||"unknown").split(",")[0],64),key=ip+name,now=Date.now();let x=rates.get(key);if(!x||x.reset<now){x={count:0,reset:now+window};rates.set(key,x)}x.count++;if(rates.size>10000)rates.clear();return x.count>max}
async function init(){
 if(!db)throw Error("database_not_connected");
 if(dbInit)return dbInit;
 dbInit=(async()=>{
 await db.unsafe("CREATE TABLE IF NOT EXISTS gildara_commerce_requests (id BIGSERIAL PRIMARY KEY, email TEXT NOT NULL, name TEXT NOT NULL, country TEXT NOT NULL, service TEXT NOT NULL, asset TEXT NOT NULL, budget_band TEXT NOT NULL, note TEXT NOT NULL DEFAULT '', consent BOOLEAN NOT NULL, referral_code TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'received', source TEXT NOT NULL DEFAULT 'portal', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW())");
 await db.unsafe("CREATE INDEX IF NOT EXISTS gildara_commerce_email ON gildara_commerce_requests(email)");
 await db.unsafe("CREATE TABLE IF NOT EXISTS gildara_member_referral_codes (user_id UUID PRIMARY KEY REFERENCES gildara_users(id) ON DELETE CASCADE, code TEXT NOT NULL UNIQUE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW())");
 await db.unsafe("CREATE TABLE IF NOT EXISTS gildara_research_billing (user_id UUID PRIMARY KEY REFERENCES gildara_users(id) ON DELETE CASCADE, stripe_customer_id TEXT, stripe_subscription_id TEXT, status TEXT NOT NULL DEFAULT 'none', updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW())");
 await db.unsafe("CREATE TABLE IF NOT EXISTS gildara_stripe_events (id TEXT PRIMARY KEY, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW())");
 await db.unsafe("ALTER TABLE gildara_commerce_requests ADD COLUMN IF NOT EXISTS owner TEXT NOT NULL DEFAULT ''");
 await db.unsafe("ALTER TABLE gildara_commerce_requests ADD COLUMN IF NOT EXISTS next_action TEXT NOT NULL DEFAULT ''");
 await db.unsafe("ALTER TABLE gildara_commerce_requests ADD COLUMN IF NOT EXISTS next_action_date DATE");
 await db.unsafe("ALTER TABLE gildara_commerce_requests ADD COLUMN IF NOT EXISTS outcome TEXT NOT NULL DEFAULT ''");
 await db.unsafe("CREATE TABLE IF NOT EXISTS gildara_commerce_audit (id BIGSERIAL PRIMARY KEY, request_id BIGINT NOT NULL, action TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW())");

 })().catch(e=>{dbInit=null;throw e});
 return dbInit;
}
async function digest(s:string){const b=await crypto.subtle.digest("SHA-256",new TextEncoder().encode(s));return [...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,"0")).join("")}
async function member(r:Request){
 if(!db)return null;
 const token=(r.headers.get("cookie")||"").split(";").map(x=>x.trim()).find(x=>x.startsWith("gildara_session="))?.slice(16)||"";
 if(!/^[a-f0-9]{64}$/.test(token))return null;
 const hash=await digest(token);
 const rows=await db.unsafe("SELECT u.id,u.email,u.display_name FROM gildara_sessions s JOIN gildara_users u ON u.id=s.user_id WHERE s.token_hash=$1 AND s.expires_at>NOW() LIMIT 1",[hash]);
 return rows[0]||null;
}
async function prices(){
 if(priceCache&&Date.now()<priceExpires)return priceCache;
 const symbols=[["XAU","Gold"],["XAG","Silver"],["XPT","Platinum"],["XPD","Palladium"]];
 const all=await Promise.allSettled(symbols.map(async([symbol,name])=>{
  const r=await fetch("https://api.gold-api.com/price/"+symbol,{signal:AbortSignal.timeout(7500)});
  if(!r.ok)throw Error("market source unavailable");
  const d=await r.json();const price=Number(d.price);
  if(!Number.isFinite(price)||price<=0)throw Error("invalid market observation");
  return {symbol,name,price,currency:"USD",unit:"troy ounce",source:"Gold API",asOf:clean(d.updatedAt||d.updated_at||new Date().toISOString(),80),executable:false};
 }));
 const quotes=all.filter(x=>x.status==="fulfilled").map((x:any)=>x.value);
 const result={ok:!!quotes.length,quotes,errors:all.filter(x=>x.status==="rejected").length,disclaimer:"Indicative observations, not executable dealer quotes; no bid/ask spread guaranteed."};
 if(quotes.length||!priceCache){priceCache=result;priceExpires=Date.now()+30000;return result}
 return {...priceCache,stale:true};
}
function stripeConfigured(){return Boolean(Bun.env.GILDARA_STRIPE_SECRET_KEY&&Bun.env.GILDARA_STRIPE_PRO_PRICE_ID&&Bun.env.GILDARA_STRIPE_WEBHOOK_SECRET)}
async function stripeApi(path:string,body:URLSearchParams){
 const r=await fetch("https://api.stripe.com/v1/"+path,{method:"POST",headers:{"authorization":"Bearer "+Bun.env.GILDARA_STRIPE_SECRET_KEY,"content-type":"application/x-www-form-urlencoded"},body:body.toString(),signal:AbortSignal.timeout(15000)});
 const d=await r.json();if(!r.ok)throw Error("Checkout provider unavailable");return d;
}
async function webhook(req:Request){
 const secret=Bun.env.GILDARA_STRIPE_WEBHOOK_SECRET;if(!secret)return new Response("Unconfigured",{status:503});
 const raw=await req.text();if(raw.length>1000000)return new Response("Too large",{status:413});
 const hdr=req.headers.get("stripe-signature")||"",t=hdr.match(/(?:^|,)t=(\d+)/)?.[1],v1=[...hdr.matchAll(/(?:^|,)v1=([a-f0-9]{64})/g)].map(x=>x[1]);
 if(!t||Math.abs(Date.now()/1000-Number(t))>300||!v1.length)return new Response("Invalid signature",{status:400});
 const key=await crypto.subtle.importKey("raw",new TextEncoder().encode(secret),{name:"HMAC",hash:"SHA-256"},false,["sign"]);
 const sign=await crypto.subtle.sign("HMAC",key,new TextEncoder().encode(t+"."+raw));
 const h=[...new Uint8Array(sign)].map(x=>x.toString(16).padStart(2,"0")).join("");
 if(!v1.some(x=>x===h))return new Response("Invalid signature",{status:400});
 const event=JSON.parse(raw);await init();
 try{await db.begin(async(tx:any)=>{
  const inserted=await tx.unsafe("INSERT INTO gildara_stripe_events(id) VALUES($1) ON CONFLICT DO NOTHING RETURNING id",[event.id]);
  if(!inserted.length)return;
  const obj=event.data?.object||{};
  if(event.type==="checkout.session.completed"){
   const uid=obj.client_reference_id||obj.metadata?.gildara_user_id;
   if(uid&&/^[a-f0-9-]{36}$/.test(uid))await tx.unsafe("INSERT INTO gildara_research_billing(user_id,stripe_customer_id,stripe_subscription_id,status) VALUES($1,$2,$3,'pending') ON CONFLICT(user_id) DO UPDATE SET stripe_customer_id=EXCLUDED.stripe_customer_id,stripe_subscription_id=EXCLUDED.stripe_subscription_id,updated_at=NOW()",[uid,obj.customer||null,obj.subscription||null]);
  }
  if(String(event.type).startsWith("customer.subscription.")){
   const uid=obj.metadata?.gildara_user_id,status=clean(obj.status,40);
   if(uid&&/^[a-f0-9-]{36}$/.test(uid))await tx.unsafe("INSERT INTO gildara_research_billing(user_id,stripe_customer_id,stripe_subscription_id,status) VALUES($1,$2,$3,$4) ON CONFLICT(user_id) DO UPDATE SET stripe_customer_id=EXCLUDED.stripe_customer_id,stripe_subscription_id=EXCLUDED.stripe_subscription_id,status=EXCLUDED.status,updated_at=NOW()",[uid,obj.customer||null,obj.id,status]);
   else if(obj.id)await tx.unsafe("UPDATE gildara_research_billing SET status=$1,updated_at=NOW() WHERE stripe_subscription_id=$2",[status,obj.id]);
  }
  if(event.type==="invoice.payment_failed"&&obj.subscription)await tx.unsafe("UPDATE gildara_research_billing SET status='past_due',updated_at=NOW() WHERE stripe_subscription_id=$1",[obj.subscription]);
 });return new Response("ok")}catch(e){console.error("webhook",String(e));return new Response("error",{status:503})}
}



async function adminAuthorized(r:Request){
 const token=Bun.env.GILDARA_ADMIN_TOKEN;
 if(!token||token.length<32)return false;
 const supplied=r.headers.get("x-gildara-admin-token")||"";
 if(supplied.length!==token.length)return false;
 const [a,b]=await Promise.all([digest(supplied),digest(token)]);return a===b;
}
